const config = $('CONFIG - Devolucoes').first().json;

const workflowName = config.workflow_name || 'ml_dashboards_mvp7_devolucoes_sync';
const schema = config.schema || 'ml_dashboards';
const timeZone = config.time_zone || 'America/Sao_Paulo';
const targetAccountId = String(config.target_account_id || '').trim();
const targetSellerId = String(config.target_seller_id || '').trim();
const claimsDaysBack = Math.min(Math.max(Number(config.claims_days_back || 30), 1), 730);
const claimsRangeChunkDays = Math.min(Math.max(Number(config.claims_range_chunk_days || 30), 1), 30);
const maxClaimsPerAccount = Math.max(Number(config.max_claims_per_account || 5000), 1);
const maxClaimsToProcessPerRun = Math.min(
  Math.max(Number(config.max_claims_to_process_per_run || 150), 1),
  500
);
const mlPageSize = Math.min(Math.max(Number(config.ml_page_size || 30), 1), 30);
const supabasePageSize = Math.min(Math.max(Number(config.supabase_page_size || 1000), 1), 1000);
const supabaseUpsertBatchSize = Math.min(Math.max(Number(config.supabase_upsert_batch_size || 100), 1), 500);
const claimConcurrency = Math.min(Math.max(Number(config.claim_concurrency || 3), 1), 10);
const requestDelayMs = Math.max(Number(config.request_delay_ms || 0), 0);
const requestMaxRetries = Math.min(Math.max(Number(config.request_max_retries || 3), 0), 6);
const staleRunAfterMinutes = Math.max(Number(config.stale_run_after_minutes || 30), 15);

const requiredConfig = [
  ['ml_client_id', config.ml_client_id],
  ['ml_client_secret', config.ml_client_secret],
  ['supabase_url', config.supabase_url],
  ['supabase_service_role_key', config.supabase_service_role_key],
];

const missingConfig = requiredConfig
  .filter(([, value]) => !value || String(value).startsWith('PREENCHA_') || String(value).includes('SEU_PROJETO'))
  .map(([name]) => name);

if (missingConfig.length) {
  throw new Error('Preencha estes campos no node CONFIG - Devolucoes: ' + missingConfig.join(', '));
}

const supabaseUrl = String(config.supabase_url).replace(/\/+$/, '');
const serviceRoleKey = config.supabase_service_role_key;
const mlClientId = config.ml_client_id;
const mlClientSecret = config.ml_client_secret;
const helpers = this.helpers;

// Etapas aceitas pela tabela devolucoes (constraint devolucoes_etapa_valida).
// O painel traduz status_atual pelo app/returns/returns-config.ts; etapa_atual
// só é usada quando o status ainda não estiver mapeado lá.
const STAGE_BY_STATUS = {
  opened: 'aberta',
  pending: 'aberta',
  label_generated: 'aberta',
  ready_to_ship: 'aberta',
  shipped: 'enviada_pelo_comprador',
  in_transit: 'enviada_pelo_comprador',
  delivered: 'recebida',
  reviewed: 'revisada',
  refunded: 'reembolsada',
  cancelled: 'encerrada_sem_devolucao',
  expired: 'encerrada_sem_devolucao',
  not_delivered: 'encerrada_sem_devolucao',
  closed: 'encerrada_sem_devolucao',
};

// Ordem dos marcos usada para reconstruir o histórico na primeira gravação.
const MILESTONE_ORDER = ['opened', 'shipped', 'delivered', 'reviewed', 'refunded'];

const DEVOLUCOES_COLUMNS = [
  'claim_id', 'return_id', 'order_id', 'mlb_id', 'titulo_anuncio', 'familia_motivo',
  'reason_id', 'status_atual', 'etapa_atual', 'data_venda', 'data_abertura',
  'data_envio_comprador', 'data_recebimento', 'data_reembolso', 'ultima_atualizacao',
  'unidades_devolvidas', 'valor_devolvido', 'custo_frete_devolucao', 'logistic_type',
].join(',');

// Colunas da fila (supabase/migrations/2026-10-08_devolucoes_fila.sql). Se a
// migração ainda não foi rodada, a ingestão segue gravando só as colunas acima.
// motivo_descricao fica de fora de propósito: o painel usa o nome do motivo de
// devolucoes_motivos quando ela está vazia.
const FILA_COLUMNS = [
  'sku', 'quantidade', 'valor_venda', 'valor_reembolsado', 'comprador_apelido',
  'etapa_ml', 'status_reclamacao', 'status_retorno', 'descricao_status', 'data_prevista',
  'destino_retorno', 'rastreio', 'prazo_acao_vendedor', 'acao_pendente', 'resultado',
];

// Ações que o Mercado Livre espera do vendedor (players[respondent].available_actions).
// Código fora desta lista aparece como "Ação do ML: <código>" e no resumo
// (acoes_vendedor_vistas), para ser traduzido depois.
const SELLER_ACTION_LABELS = {
  send_message_to_complainant: 'Responder o comprador',
  send_message_to_mediator: 'Responder ao ML na mediação',
  refund: 'Reembolsar o comprador',
  partial_refund: 'Oferecer reembolso parcial',
  allow_partial_refund: 'Oferecer reembolso parcial',
  allow_return: 'Aceitar a devolução',
  allow_return_label: 'Liberar a etiqueta de devolução',
  open_dispute: 'Pedir ajuda ao ML (mediação)',
  send_potential_shipping: 'Informar o envio do produto',
  add_shipping_evidence: 'Enviar comprovante de envio',
  send_tracking_number: 'Informar o rastreio',
  send_attachments: 'Enviar anexos ao caso',
  return_review: 'Revisar o produto e informar ao ML',
  return_review_ok: 'Revisar o produto e informar ao ML',
  return_review_fail: 'Revisar o produto e informar ao ML',
  return_review_unified: 'Revisar o produto e informar ao ML',
  return_review_unified_ok: 'Revisar o produto e informar ao ML',
  return_review_unified_fail: 'Revisar o produto e informar ao ML',
  recontact: 'Responder ao recontato do caso',
  change_product: 'Trocar o produto',
};

// Condição do produto na revisão da devolução (coluna Resultado).
const REVIEW_CONDITION_LABELS = {
  saleable: 'Apto para venda',
  unsaleable: 'Não apto para venda',
  discard: 'Descartado',
  no_testable: 'Não testável',
  missing: 'Produto não chegou',
};

const CLAIM_STAGE_LABELS = {
  claim: 'reclamação',
  dispute: 'mediação',
  recontact: 'recontato',
  stale: 'sem movimento',
  none: 'sem etapa',
};

const MONEY_STATUS_LABELS = {
  retained: 'retido',
  refunded: 'devolvido ao comprador',
  available: 'liberado ao vendedor',
};

const saoPauloDateFormat = new Intl.DateTimeFormat('en-CA', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

function nowIso() {
  return new Date().toISOString();
}

function sleep(ms) {
  if (!ms) return Promise.resolve();
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function firstRow(response) {
  if (Array.isArray(response)) return response[0] || null;
  return response || null;
}

function normalizeNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function normalizeInteger(value) {
  const parsed = normalizeNumber(value);
  return parsed === null ? null : Math.trunc(parsed);
}

function normalizeDate(value) {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function timeOf(value) {
  const parsed = value ? new Date(value).getTime() : Number.NaN;
  return Number.isFinite(parsed) ? parsed : 0;
}

function maxDate(...values) {
  const times = values.map(timeOf).filter((time) => time > 0);
  return times.length ? new Date(Math.max(...times)).toISOString() : null;
}

function minDate(...values) {
  const times = values.map(timeOf).filter((time) => time > 0);
  return times.length ? new Date(Math.min(...times)).toISOString() : null;
}

function saoPauloDate(value) {
  const iso = normalizeDate(value);
  return iso ? saoPauloDateFormat.format(new Date(iso)) : null;
}

function formatMlRangeDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error('Data invalida para busca de claims.');
  const saoPauloTime = new Date(date.getTime() - 3 * 60 * 60 * 1000);
  return saoPauloTime.toISOString().replace('Z', '-0300');
}

function normalizeText(value) {
  if (value === null || value === undefined || value === '') return null;
  return String(value);
}

function lower(value) {
  const text = normalizeText(value);
  return text ? text.trim().toLowerCase() : null;
}

function normalizeTextArray(value) {
  if (!Array.isArray(value)) return [];
  return value
    .filter((item) => item !== null && item !== undefined)
    .map((item) => typeof item === 'string' ? item : JSON.stringify(item));
}

function compactError(error) {
  const responseBody = error?.response?.body ?? error?.response?.data ?? error?.body ?? error?.data ?? null;
  return {
    name: error?.name || null,
    message: error?.message || String(error),
    statusCode: errorStatus(error) || null,
    description: typeof error?.description === 'string' ? error.description.slice(0, 2000) : null,
    method: error?.requestMethod || error?.config?.method || error?.options?.method || null,
    url: error?.requestUrl || error?.config?.url || error?.options?.url || null,
    body: typeof responseBody === 'string' ? responseBody.slice(0, 2000) : responseBody,
  };
}

// O n8n entrega o código HTTP em lugares diferentes conforme a versão
// (statusCode, response.status, httpCode) ou só na mensagem
// ("Request failed with status code 400").
function errorStatus(error) {
  const direct = Number(
    error?.statusCode || error?.response?.statusCode || error?.response?.status || error?.httpCode || error?.status || 0
  );
  if (direct) return direct;
  const match = String(error?.message || '').match(/status code (\d{3})/i);
  return match ? Number(match[1]) : 0;
}

// Coluna inexistente no Supabase (42703 / PGRST204): a migração da fila ainda
// não foi rodada.
function isMissingColumnError(error) {
  const status = errorStatus(error);
  const details = JSON.stringify(compactError(error));
  return (status === 400 || status === 404)
    && /42703|PGRST204|column .{0,80}(does not exist|not find)/i.test(details);
}

function chunkArray(values, size) {
  const chunks = [];
  for (let index = 0; index < values.length; index += size) {
    chunks.push(values.slice(index, index + size));
  }
  return chunks;
}

function buildQuery(params) {
  return Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value))
    .join('&');
}

function buildMlQuery(params) {
  return Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => {
      const encodedValue = encodeURIComponent(value)
        .replace(/%3A/gi, ':')
        .replace(/%2C/gi, ',');
      return encodeURIComponent(key) + '=' + encodedValue;
    })
    .join('&');
}

function formEncode(payload) {
  return Object.entries(payload)
    .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value))
    .join('&');
}

function isFullResponse(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
    && typeof value.statusCode === 'number'
    && Boolean(value.headers) && typeof value.headers === 'object'
    && 'body' in value;
}

async function requestWithRetry(options, retries = requestMaxRetries) {
  let lastError = null;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      const response = await helpers.httpRequest({ timeout: 120000, json: true, ...options });
      // Com returnFullResponse + ignoreHttpStatusErrors, o erro chega como
      // resposta e o corpo (com o motivo do Supabase) não se perde.
      if (!options.returnFullResponse || !isFullResponse(response)) return response;
      if (response.statusCode < 400) return response.body;
      const httpError = new Error('Request failed with status code ' + response.statusCode);
      httpError.statusCode = response.statusCode;
      httpError.response = { status: response.statusCode, body: response.body };
      throw httpError;
    } catch (error) {
      error.requestUrl = options.url;
      error.requestMethod = options.method;
      lastError = error;
      const status = errorStatus(error);
      const retryable = status === 429 || status >= 500 || status === 0;

      if (!retryable || attempt >= retries) throw error;
      await sleep(500 * Math.pow(2, attempt));
    }
  }

  throw lastError;
}

async function supabaseRequest(method, resourcePath, body = undefined, prefer = undefined) {
  const headers = {
    apikey: serviceRoleKey,
    Authorization: 'Bearer ' + serviceRoleKey,
    Accept: 'application/json',
    'Content-Type': 'application/json',
    'Accept-Profile': schema,
  };

  if (method !== 'GET') headers['Content-Profile'] = schema;
  if (prefer) headers.Prefer = prefer;

  const options = {
    method,
    url: supabaseUrl + '/rest/v1' + resourcePath,
    headers,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  };

  if (body !== undefined) options.body = body;
  return await requestWithRetry(options);
}

async function upsertRows(table, rows, onConflict) {
  if (!rows.length) return;

  for (const chunk of chunkArray(rows, supabaseUpsertBatchSize)) {
    await supabaseRequest(
      'POST',
      '/' + table + '?on_conflict=' + encodeURIComponent(onConflict),
      chunk,
      'resolution=merge-duplicates,return=minimal'
    );
  }
}

async function fetchPaged(table, params, maxRows) {
  const rows = [];

  for (let offset = 0; rows.length < maxRows; offset += supabasePageSize) {
    const limit = Math.min(supabasePageSize, maxRows - rows.length);
    const response = await supabaseRequest(
      'GET',
      '/' + table + '?' + buildQuery({ ...params, limit, offset })
    );
    const page = Array.isArray(response) ? response : [];
    rows.push(...page);
    if (page.length < limit) break;
  }

  return rows.slice(0, maxRows);
}

// -----------------------------------------------------------------------------
// sync_runs: registro de execução. Se a tabela não existir, a sincronização
// segue sem registro (não é motivo para parar a ingestão).
// -----------------------------------------------------------------------------
async function startSyncRun(accountId) {
  try {
    const staleBefore = new Date(Date.now() - staleRunAfterMinutes * 60 * 1000).toISOString();
    await supabaseRequest(
      'PATCH',
      '/sync_runs?' + buildQuery({
        account_id: 'eq.' + accountId,
        workflow_name: 'eq.' + workflowName,
        status: 'eq.running',
        started_at: 'lt.' + staleBefore,
      }),
      {
        status: 'error',
        finished_at: nowIso(),
        error_message: 'Execucao N8N anterior ficou orfa; encerrada automaticamente antes da retomada.',
        raw_error: { code: 'orphaned_n8n_execution', recovered_at: nowIso() },
      },
      'return=minimal'
    );
    const response = await supabaseRequest(
      'POST',
      '/sync_runs',
      { account_id: accountId, workflow_name: workflowName, status: 'running', started_at: nowIso() },
      'return=representation'
    );
    return { runId: firstRow(response)?.id || null, logError: null };
  } catch (error) {
    return { runId: null, logError: compactError(error) };
  }
}

async function finishSyncRun(runId, status, error = null) {
  if (!runId) return null;
  const payload = { status, finished_at: nowIso() };
  if (error) {
    const normalized = compactError(error);
    payload.error_message = normalized.message;
    payload.raw_error = normalized;
  }
  try {
    await supabaseRequest('PATCH', '/sync_runs?id=eq.' + encodeURIComponent(runId), payload, 'return=minimal');
    return null;
  } catch (logError) {
    return compactError(logError);
  }
}

// -----------------------------------------------------------------------------
// Mercado Livre
// -----------------------------------------------------------------------------
async function refreshMercadoLivreToken(refreshToken) {
  return await requestWithRetry({
    method: 'POST',
    url: 'https://api.mercadolibre.com/oauth/token',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/json',
    },
    body: formEncode({
      grant_type: 'refresh_token',
      client_id: mlClientId,
      client_secret: mlClientSecret,
      refresh_token: refreshToken,
    }),
  });
}

async function ensureAccessToken(account) {
  let accessToken = account.access_token || null;
  let sellerId = account.ml_user_id || null;
  const expiresAt = account.expires_at ? new Date(account.expires_at).getTime() : 0;
  const valid = accessToken && expiresAt > Date.now() + 5 * 60 * 1000;

  if (!valid) {
    if (!account.refresh_token) throw new Error('Conta ' + account.account_id + ' sem refresh_token.');

    const token = await refreshMercadoLivreToken(account.refresh_token);
    if (!token?.access_token) throw new Error('Mercado Livre nao retornou access_token ao renovar OAuth.');

    accessToken = token.access_token;
    sellerId = token.user_id ?? sellerId;
    const nextExpiresAt = token.expires_in
      ? new Date(Date.now() + Math.max(Number(token.expires_in) - 300, 0) * 1000).toISOString()
      : null;

    await supabaseRequest(
      'POST',
      '/oauth_tokens?on_conflict=account_id',
      {
        account_id: account.account_id,
        ml_user_id: sellerId,
        access_token: accessToken,
        refresh_token: token.refresh_token || account.refresh_token,
        token_type: token.token_type || 'Bearer',
        expires_in: token.expires_in ?? null,
        scope: token.scope ?? null,
        expires_at: nextExpiresAt,
        updated_at: nowIso(),
      },
      'resolution=merge-duplicates,return=minimal'
    );
  }

  if (!accessToken || !sellerId) {
    throw new Error('Nao foi possivel obter access_token e seller_id para ' + account.account_id + '.');
  }

  return { accessToken, sellerId: Number(sellerId) };
}

async function mlGet(accessToken, resourcePath, params = undefined) {
  const query = params ? '?' + buildMlQuery(params) : '';
  return await requestWithRetry({
    method: 'GET',
    url: 'https://api.mercadolibre.com' + resourcePath + query,
    headers: { Authorization: 'Bearer ' + accessToken, Accept: 'application/json' },
  });
}

// 404 = o recurso não existe para esta claim (normal). Outros erros são
// registrados no resumo, sem derrubar a claim.
async function optionalMlGet(accessToken, resourcePath, endpoint, params = undefined) {
  try {
    const data = await mlGet(accessToken, resourcePath, params);
    return { endpoint, data, error: null, notFound: false };
  } catch (error) {
    if (errorStatus(error) === 404) {
      return { endpoint, data: null, error: null, notFound: true };
    }
    return { endpoint, data: null, error: compactError(error), notFound: false };
  }
}

async function searchClaims(accessToken, sellerId, filters) {
  const rows = [];
  let total = null;

  for (let offset = 0; rows.length < maxClaimsPerAccount; offset += mlPageSize) {
    const response = await mlGet(accessToken, '/post-purchase/v1/claims/search', {
      ...filters,
      'players.role': 'respondent',
      'players.user_id': sellerId,
      limit: mlPageSize,
      offset,
    });
    const page = Array.isArray(response?.data) ? response.data : [];
    total = normalizeInteger(response?.paging?.total) ?? total;
    rows.push(...page);
    if (page.length < mlPageSize || (total !== null && rows.length >= total)) break;
    await sleep(requestDelayMs);
  }

  return { rows: rows.slice(0, maxClaimsPerAccount), total };
}

async function searchClaimsByRange(accessToken, sellerId, field, fromDate, toDate) {
  const merged = new Map();
  let windows = 0;
  let cursor = new Date(fromDate);
  const finalDate = new Date(toDate);

  while (cursor < finalDate && merged.size < maxClaimsPerAccount) {
    const chunkEnd = new Date(Math.min(
      cursor.getTime() + claimsRangeChunkDays * 24 * 60 * 60 * 1000,
      finalDate.getTime()
    ));
    const range = field + ':after:' + formatMlRangeDate(cursor)
      + ',before:' + formatMlRangeDate(chunkEnd);
    // A busca é recusada (400) sem o filtro status.
    const openedResult = await searchClaims(accessToken, sellerId, { range, status: 'opened' });
    const closedResult = await searchClaims(accessToken, sellerId, { range, status: 'closed' });
    windows += 1;
    for (const claim of [...openedResult.rows, ...closedResult.rows]) {
      if (claim?.id) merged.set(String(claim.id), claim);
    }
    cursor = chunkEnd;
    await sleep(requestDelayMs);
  }

  return { rows: Array.from(merged.values()).slice(0, maxClaimsPerAccount), windows };
}

function claimHasReturn(claim) {
  const related = normalizeTextArray(claim?.related_entities).map((value) => value.toLowerCase());
  const type = String(claim?.type || '').toLowerCase();
  return related.some((value) => value === 'return' || value === 'returns')
    || type === 'return'
    || type === 'change';
}

function normalizeReturnObjects(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.filter((item) => item && typeof item === 'object');
  if (Array.isArray(value.returns)) return value.returns.filter((item) => item && typeof item === 'object');
  if (Array.isArray(value.data)) return value.data.filter((item) => item && typeof item === 'object');
  return typeof value === 'object' ? [value] : [];
}

function reasonFamily(reasonId) {
  const prefix = String(reasonId || '').trim().slice(0, 3).toUpperCase();
  return prefix === 'PDD' || prefix === 'PNR' ? prefix : null;
}

// Status gravado em status_atual. É o status da devolução na API, com duas
// exceções para refletir o andamento real:
//   - dinheiro já devolvido ao comprador (status_money = refunded) -> refunded;
//   - produto entregue à loja e já revisado -> reviewed.
function effectiveStatus(returnData, hasReview) {
  const raw = lower(returnData?.status);
  if (lower(returnData?.status_money) === 'refunded') return 'refunded';
  if (raw === 'delivered' && hasReview) return 'reviewed';
  return raw;
}

function stageOf(status) {
  return status ? STAGE_BY_STATUS[status] || null : null;
}

function usableReturnShipments(returnData) {
  const shipments = Array.isArray(returnData?.shipments) ? returnData.shipments : [];
  return shipments.filter((shipment) => shipment?.shipment_id || shipment?.id);
}

function shipmentIdOf(shipment) {
  return normalizeText(shipment?.shipment_id ?? shipment?.id);
}

// 'warehouse' = CD do Mercado Livre (Full); 'seller' = endereço da loja
// (a API manda "seller_address").
function destinationKind(shipment) {
  const name = lower(shipment?.destination?.name ?? shipment?.destination);
  if (!name) return null;
  if (name.includes('warehouse')) return 'warehouse';
  if (name.includes('seller')) return 'seller';
  return null;
}

// 1º trecho (comprador → loja ou CD): base das datas de postagem e recebimento.
function pickReturnShipment(returnData) {
  const usable = usableReturnShipments(returnData);
  return usable.find((shipment) => lower(shipment.type) !== 'return_from_triage') || usable[0] || null;
}

// Trecho atual: depois da revisão no CD, o ML cria um envio do CD para a loja
// (return_from_triage). É ele que diz destino, rastreio e previsão de hoje.
function currentReturnShipment(returnData) {
  const usable = usableReturnShipments(returnData);
  return usable.find((shipment) => lower(shipment.type) === 'return_from_triage')
    || usable[usable.length - 1]
    || null;
}

function emptyShipmentInfo() {
  return {
    recognized: false,
    shipped: null,
    delivered: null,
    estimated: null,
    tracking: null,
    status: null,
    substatus: null,
  };
}

// Datas, status, rastreio e previsão de um envio de volta. Aceita os formatos
// conhecidos da API: o histórico (/shipments/{id}/history, objeto com
// date_history), uma lista de eventos ou o próprio envio (status_history).
// recognized = a resposta veio num formato conhecido, mesmo que a data ainda
// não exista (pacote ainda no ponto de coleta, por exemplo).
function shipmentInfo(value) {
  const info = emptyShipmentInfo();
  if (!value || typeof value !== 'object') return info;

  const listKeys = ['data', 'history', 'results', 'events', 'status_history'];
  const entries = Array.isArray(value)
    ? value
    : listKeys.map((key) => value?.[key]).find(Array.isArray) || [];

  for (const entry of entries) {
    const status = lower(entry?.status);
    const date = normalizeDate(entry?.date ?? entry?.date_created ?? entry?.last_updated ?? entry?.date_time);
    if (!date) continue;
    if (status === 'shipped' || status === 'in_transit') info.shipped = minDate(info.shipped, date);
    if (status === 'delivered') info.delivered = minDate(info.delivered, date);
  }

  const objectOrNull = (item) => (item && typeof item === 'object' && !Array.isArray(item) ? item : null);
  const dateHistory = objectOrNull(value.date_history);
  const statusHistory = objectOrNull(value.status_history);
  for (const source of [dateHistory, statusHistory, Array.isArray(value) ? null : value]) {
    if (!source) continue;
    info.shipped = info.shipped || normalizeDate(source.date_shipped);
    info.delivered = info.delivered || normalizeDate(source.date_delivered);
    info.estimated = info.estimated || normalizeDate(source.date_delivered_estimated);
  }

  if (!Array.isArray(value)) {
    info.estimated = info.estimated
      || normalizeDate(value.shipping_option?.estimated_delivery_time?.date)
      || normalizeDate(value.estimated_delivery_time?.date);
    info.tracking = normalizeText(value.tracking_number) || normalizeText(value.return_tracking_number);
    info.status = lower(value.status);
    info.substatus = lower(value.substatus);
  }

  info.recognized = Boolean(dateHistory || statusHistory || entries.length);
  return info;
}

function mergeShipmentInfo(primary, secondary) {
  const merged = { ...primary };
  for (const [key, item] of Object.entries(secondary)) {
    if (key === 'recognized') merged.recognized = primary.recognized || secondary.recognized;
    else if (merged[key] === null || merged[key] === undefined) merged[key] = item;
  }
  return merged;
}

// Amostra do formato de uma resposta, só com chaves de status e datas (nunca
// nomes, endereços ou outros dados pessoais), para ajustar a leitura.
function describeShape(value) {
  const keep = /^(status|substatus|type|mode)$|date|_at$|updated/i;
  function slim(entry) {
    if (!entry || typeof entry !== 'object') return entry;
    const result = {};
    for (const [key, item] of Object.entries(entry)) {
      if (!keep.test(key)) continue;
      result[key] = item && typeof item === 'object' ? slim(item) : item;
    }
    return result;
  }
  if (value === null || value === undefined) return null;
  if (Array.isArray(value)) return { tipo: 'lista', tamanho: value.length, itens: value.slice(0, 6).map(slim) };
  if (typeof value !== 'object') return { tipo: typeof value };
  return { tipo: 'objeto', chaves: Object.keys(value).slice(0, 40), datas_e_status: slim(value) };
}

function logisticTypeOf(shipment) {
  return lower(shipment?.logistic_type ?? shipment?.logistic?.type);
}

// Itens devolvidos × preço do item no pedido. Nunca o valor do pedido inteiro.
function returnedValues(returnData, orderId, order) {
  const returnedOrders = (Array.isArray(returnData?.orders) ? returnData.orders : [])
    .filter((item) => item && (!orderId || String(item.order_id) === String(orderId)));
  const orderItems = Array.isArray(order?.order_items) ? order.order_items : [];

  let units = null;
  let amount = null;
  let mlbId = null;
  let title = null;

  for (const returned of returnedOrders) {
    const quantity = normalizeInteger(returned.return_quantity ?? returned.total_quantity);
    const itemId = normalizeText(returned.item_id);
    const variationId = normalizeText(returned.variation_id);
    if (quantity !== null) units = (units || 0) + quantity;
    mlbId = mlbId || itemId;

    const orderItem = orderItems.find((entry) => {
      if (normalizeText(entry?.item?.id) !== itemId) return false;
      const entryVariation = normalizeText(entry?.item?.variation_id);
      return !variationId || !entryVariation || entryVariation === variationId;
    }) || (orderItems.length === 1 ? orderItems[0] : null);

    if (orderItem) {
      title = title || normalizeText(orderItem.item?.title);
      const unitPrice = normalizeNumber(orderItem.unit_price);
      if (unitPrice !== null && quantity !== null) amount = (amount || 0) + quantity * unitPrice;
    }
  }

  if (!mlbId && orderItems.length) {
    mlbId = normalizeText(orderItems[0]?.item?.id);
    title = title || normalizeText(orderItems[0]?.item?.title);
  }

  return {
    units,
    amount: amount === null ? null : Math.round(amount * 100) / 100,
    mlbId,
    title,
  };
}

function stageDate(status, dates) {
  const stage = stageOf(status);
  if (stage === 'aberta') return dates.data_abertura;
  if (stage === 'enviada_pelo_comprador') return dates.data_envio_comprador;
  if (stage === 'recebida') return dates.data_recebimento;
  if (stage === 'revisada') return dates.review_date;
  if (stage === 'reembolsada') return dates.data_reembolso;
  return null;
}

// -----------------------------------------------------------------------------
// Colunas da fila (planilha pcxpress-fila-devolucoes, aba Devoluções, A–X)
// -----------------------------------------------------------------------------

// Ações do vendedor na reclamação. Só as obrigatórias contam como "ação
// pendente": as opcionais (por exemplo, pedir mediação) estão quase sempre
// disponíveis e encheriam a fila de falsos pendentes.
function sellerActions(claim) {
  const players = Array.isArray(claim?.players) ? claim.players : [];
  const seller = players.find((player) => lower(player?.role) === 'respondent')
    || players.find((player) => lower(player?.type) === 'seller');
  const actions = (Array.isArray(seller?.available_actions) ? seller.available_actions : [])
    .map((item) => ({
      action: lower(typeof item === 'string' ? item : item?.action),
      mandatory: item?.mandatory === true,
      dueDate: normalizeDate(item?.due_date),
    }))
    .filter((item) => item.action);
  return { known: Boolean(seller), actions, mandatory: actions.filter((item) => item.mandatory) };
}

function actionLabel(action) {
  return SELLER_ACTION_LABELS[action] || 'Ação do ML: ' + action;
}

// Etapa (coluna M): Reclamação / Mediação / Devolução / Retorno (não entregue).
// "Retorno (não entregue)" = devolução numa reclamação de produto não recebido
// (PNR): o pacote não chegou ao comprador e está voltando para a loja.
function caseTypeOf(claim, hasReturn) {
  if (lower(claim?.stage) === 'dispute') return 'Mediação';
  if (hasReturn && reasonFamily(claim?.reason_id) === 'PNR') return 'Retorno (não entregue)';
  return hasReturn ? 'Devolução' : 'Reclamação';
}

// Condição do produto na revisão (saleable, unsaleable...). Aceita a revisão
// com ou sem a lista resource_reviews.
function reviewConditionOf(reviews) {
  let condition = null;
  for (const review of reviews) {
    const items = Array.isArray(review?.resource_reviews) && review.resource_reviews.length
      ? review.resource_reviews
      : [review];
    for (const item of items) {
      condition = lower(item?.product_condition ?? item?.condition) || condition;
    }
  }
  return condition;
}

function resolutionTextOf(claim) {
  if (lower(claim?.status) !== 'closed') return null;
  const benefited = claim?.resolution?.benefited;
  const parties = (Array.isArray(benefited) ? benefited : [benefited]).map(lower).filter(Boolean);
  const buyer = parties.includes('complainant');
  const seller = parties.includes('respondent');
  if (buyer && seller) return 'Acordo';
  if (buyer) return 'A favor do comprador';
  if (seller) return 'A favor do vendedor';
  return null;
}

// Status do retorno (coluna O), com o vocabulário da planilha.
function returnStatusTextOf(context) {
  const { claim, rawStatus, caseType, firstKind, currentKind, fromTriage, hasReview } = context;
  const kind = currentKind || firstKind;
  const moving = ['shipped', 'in_transit', 'delivered'].includes(rawStatus);

  if (lower(claim?.status) === 'closed') {
    return lower(context.returnData?.status_money) === 'refunded' ? 'Encerrado — reembolsado ao comprador' : 'Encerrado';
  }
  if (lower(claim?.stage) === 'dispute' && !moving) return 'Em análise pelo ML';
  if (['pending', 'opened', 'label_generated', 'ready_to_ship'].includes(rawStatus)) {
    return 'Em preparação pelo comprador';
  }
  if (rawStatus === 'shipped' || rawStatus === 'in_transit') {
    if (caseType === 'Retorno (não entregue)') return 'Voltando ao vendedor';
    if (fromTriage) return 'Revisado — a caminho do vendedor';
    if (kind === 'warehouse') return 'A caminho do CD do ML para revisão';
    if (kind === 'seller') return 'A caminho do vendedor';
    return 'A caminho (destino não informado)';
  }
  if (rawStatus === 'delivered') {
    if (kind === 'warehouse') return hasReview ? 'Revisado — produto parado no CD do ML' : 'Em revisão no CD do ML';
    if (kind === 'seller') return hasReview ? 'Revisado — entregue ao vendedor' : 'Entregue ao vendedor — revisão pendente';
    return hasReview ? 'Revisado' : 'Entregue — revisão pendente';
  }
  const closedLabels = {
    not_delivered: 'Não entregue',
    cancelled: 'Cancelado',
    expired: 'Expirado',
    closed: 'Encerrado',
    failed: 'Falhou',
  };
  if (closedLabels[rawStatus]) return closedLabels[rawStatus];
  return rawStatus ? 'Status do ML: ' + rawStatus : 'Status não informado';
}

function destinationTextOf(kind, hasReturn) {
  if (!hasReturn) return '—';
  if (kind === 'warehouse') return 'CD Mercado Livre (Full)';
  if (kind === 'seller') return 'Vendedor';
  return 'A definir';
}

// Ação pendente (coluna U) e prazo (coluna T). Sem ação obrigatória, diz o que
// se espera: começa com "Nenhuma", como na planilha.
function pendingActionOf(context) {
  const { claim, actions, rawStatus, firstKind, currentKind, hasReview, reviewCondition } = context;
  if (lower(claim?.status) === 'closed') return { text: 'Nenhuma — caso encerrado', dueDate: null };

  if (actions.mandatory.length) {
    const labels = Array.from(new Set(actions.mandatory.map((item) => actionLabel(item.action))));
    return { text: labels.join(' · '), dueDate: minDate(...actions.mandatory.map((item) => item.dueDate)) };
  }

  const kind = currentKind || firstKind;
  let text = 'Nenhuma — aguardar';
  if (lower(claim?.stage) === 'dispute') text = 'Nenhuma — aguardar decisão do ML';
  else if (['pending', 'opened', 'label_generated', 'ready_to_ship'].includes(rawStatus)) {
    text = 'Nenhuma — aguardar envio do comprador';
  } else if (rawStatus === 'shipped' || rawStatus === 'in_transit') {
    text = kind === 'warehouse' ? 'Nenhuma — aguardar resultado da revisão' : 'Nenhuma — aguardar chegada';
  } else if (rawStatus === 'delivered' && kind === 'warehouse') {
    if (!hasReview) text = 'Nenhuma — aguardar resultado da revisão';
    else if (reviewCondition !== 'saleable') text = 'Solicitar a retirada do produto no CD';
    else text = 'Nenhuma — produto volta ao estoque Full';
  }
  return { text, dueDate: null };
}

// Descrição do status (coluna P). A API não traz o texto do painel do ML;
// esta é a leitura dos códigos, para conferência.
function statusDescriptionOf(context) {
  const { claim, returnData, shipment, reviewCondition } = context;
  const parts = [];
  const claimStatus = lower(claim?.status);
  const stage = lower(claim?.stage);
  if (claimStatus) {
    parts.push('Reclamação ' + (claimStatus === 'opened' ? 'aberta' : claimStatus === 'closed' ? 'fechada' : claimStatus)
      + (stage ? ' (' + (CLAIM_STAGE_LABELS[stage] || stage) + ')' : ''));
  }
  const rawStatus = lower(returnData?.status);
  if (rawStatus) {
    const money = lower(returnData?.status_money);
    parts.push('devolução ' + rawStatus + (money ? ', dinheiro ' + (MONEY_STATUS_LABELS[money] || money) : ''));
  }
  if (shipment?.status) {
    parts.push('envio ' + shipment.status + (shipment.substatus ? ' / ' + shipment.substatus : ''));
  }
  if (reviewCondition) parts.push('revisão: ' + (REVIEW_CONDITION_LABELS[reviewCondition] || reviewCondition));
  return parts.length ? parts.join(' · ') : null;
}

// SKU, Qtd, valor da venda, valor reembolsado e apelido do comprador (G–K).
// Só o apelido: nunca nome, CPF, endereço ou telefone.
function orderQueueValues(order, returnData, orderId) {
  const orderItems = Array.isArray(order?.order_items) ? order.order_items : [];
  const returned = (Array.isArray(returnData?.orders) ? returnData.orders : [])
    .find((item) => item && (!orderId || String(item.order_id) === String(orderId)));
  const returnedItemId = normalizeText(returned?.item_id);
  const orderItem = orderItems.find((entry) => normalizeText(entry?.item?.id) === returnedItemId)
    || orderItems[0]
    || null;

  const itemsTotal = orderItems.reduce((total, entry) => {
    const price = normalizeNumber(entry?.unit_price);
    const quantity = normalizeNumber(entry?.quantity);
    return price === null || quantity === null ? total : (total ?? 0) + price * quantity;
  }, null);
  const saleAmount = normalizeNumber(order?.total_amount) ?? itemsTotal;

  const payments = Array.isArray(order?.payments) ? order.payments : [];
  const refunds = payments
    .map((payment) => normalizeNumber(payment?.transaction_amount_refunded))
    .filter((value) => value !== null);
  const refunded = refunds.length ? refunds.reduce((total, value) => total + value, 0) : null;

  const round = (value) => (value === null ? null : Math.round(value * 100) / 100);
  const nonNegative = (value) => (value !== null && value >= 0 ? value : null);
  return {
    sku: normalizeText(orderItem?.item?.seller_sku) || normalizeText(orderItem?.item?.seller_custom_field),
    quantidade: nonNegative(normalizeInteger(orderItem?.quantity)),
    valor_venda: nonNegative(round(saleAmount)),
    valor_reembolsado: nonNegative(round(refunded)),
    comprador_apelido: normalizeText(order?.buyer?.nickname),
  };
}

function buildHistoryRows(accountId, claimId, row, stored, reviewDate, returnUpdatedAt) {
  const status = row.status_atual;
  if (!status) return [];
  const dates = { ...row, review_date: reviewDate };
  const fallbackDate = returnUpdatedAt || row.ultima_atualizacao || nowIso();

  // Já existia: grava uma linha só quando o status mudou.
  if (stored) {
    if (lower(stored.status_atual) === status) return [];
    return [{
      account_id: accountId,
      claim_id: claimId,
      status,
      etapa: stageOf(status),
      data_status: stageDate(status, dates) || fallbackDate,
      synced_at: nowIso(),
    }];
  }

  // Primeira gravação: reconstrói os marcos conhecidos até o status atual, para
  // que "dias parada na etapa" já saia certo na carga inicial.
  const currentIndex = MILESTONE_ORDER.indexOf(status);
  const milestones = [
    ['opened', row.data_abertura],
    ['shipped', row.data_envio_comprador],
    ['delivered', row.data_recebimento],
    ['reviewed', reviewDate],
    ['refunded', row.data_reembolso],
  ].filter(([milestone, date]) => {
    if (!date) return false;
    if (currentIndex === -1) return true;
    return MILESTONE_ORDER.indexOf(milestone) <= currentIndex;
  });

  if (!milestones.some(([milestone]) => milestone === status)) {
    milestones.push([status, stageDate(status, dates) || fallbackDate]);
  }

  return milestones.map(([milestone, date]) => ({
    account_id: accountId,
    claim_id: claimId,
    status: milestone,
    etapa: stageOf(milestone),
    data_status: normalizeDate(date),
    synced_at: nowIso(),
  })).filter((historyRow) => historyRow.data_status);
}

async function processClaim(accountId, accessToken, searchClaim, stored, options = {}) {
  const filaAvailable = Boolean(options.filaAvailable);
  const claimId = String(searchClaim.id);
  const optionalResults = [];
  let claim = searchClaim;
  let detailIssue = null;
  let detailLoaded = false;

  async function loadDetail() {
    detailLoaded = true;
    try {
      claim = { ...claim, ...(await mlGet(accessToken, '/post-purchase/v1/claims/' + encodeURIComponent(claimId))) };
    } catch (error) {
      // 400/403/404: segue com o resumo da busca (sem ações do vendedor, se
      // faltarem). Token inválido (401) e limite de chamadas (429) param a claim.
      const status = errorStatus(error);
      if (status < 400 || status >= 500 || status === 401 || status === 429) throw error;
      detailIssue = { claim_id: claimId, detail_status: status };
    }
  }

  // O resumo da busca costuma bastar. O detalhe só é chamado se faltar algo.
  const needsDetail = !claim.reason_id || !claim.resource_id || !Array.isArray(claim.related_entities);
  if (needsDetail) await loadDetail();

  const claimUpdatedAt = maxDate(claim.last_updated, claim.date_created, searchClaim.last_updated);

  if (!claimHasReturn(claim)) {
    return { kind: 'no_return', claimId, claimUpdatedAt, detailIssue };
  }

  // Ação pendente e prazo do vendedor vêm de players[].available_actions. Se a
  // busca não trouxe os participantes de uma reclamação aberta, lê o detalhe.
  const claimOpen = lower(claim.status) === 'opened';
  if (filaAvailable && claimOpen && !Array.isArray(claim.players) && !detailLoaded) await loadDetail();

  const returnResult = await optionalMlGet(
    accessToken,
    '/post-purchase/v2/claims/' + encodeURIComponent(claimId) + '/returns',
    'return'
  );
  optionalResults.push(returnResult);
  const returnData = normalizeReturnObjects(returnResult.data).find((item) => item?.id) || null;

  if (!returnData) {
    return {
      kind: returnResult.error ? 'return_error' : 'no_return',
      claimId,
      claimUpdatedAt,
      detailIssue,
      optionalErrors: returnResult.error ? [{ claim_id: claimId, endpoint: 'return', error: returnResult.error }] : [],
    };
  }

  const returnId = String(returnData.id);
  const related = normalizeTextArray(returnData.related_entities).map((value) => value.toLowerCase());

  // Revisão do produto (etapa "revisada").
  let reviewDate = null;
  let reviews = [];
  if (related.includes('reviews')) {
    const reviewResult = await optionalMlGet(
      accessToken,
      '/post-purchase/v1/returns/' + encodeURIComponent(returnId) + '/reviews',
      'reviews'
    );
    optionalResults.push(reviewResult);
    reviews = Array.isArray(reviewResult.data?.reviews) ? reviewResult.data.reviews : [];
    for (const review of reviews) {
      reviewDate = minDate(reviewDate, review?.date_created, review?.last_updated);
    }
  }
  const reviewCondition = reviewConditionOf(reviews);

  const status = effectiveStatus(returnData, Boolean(reviewDate));

  // Frete de devolução: busca enquanto ainda não houver valor gravado.
  let returnCost = normalizeNumber(stored?.custo_frete_devolucao);
  if (returnCost === null) {
    const costResult = await optionalMlGet(
      accessToken,
      '/post-purchase/v1/claims/' + encodeURIComponent(claimId) + '/charges/return-cost',
      'return_cost'
    );
    optionalResults.push(costResult);
    const amount = normalizeNumber(costResult.data?.amount);
    const currency = normalizeText(costResult.data?.currency_id);
    if (amount !== null && amount >= 0 && (!currency || currency === 'BRL')) returnCost = amount;
  }

  // Envios da devolução. O 1º trecho (comprador → loja ou CD) dá as datas de
  // postagem e recebimento. O trecho atual (por exemplo, do CD para a loja
  // depois da revisão) dá destino, rastreio e previsão de chegada.
  let buyerShippedAt = normalizeDate(stored?.data_envio_comprador);
  let receivedAt = normalizeDate(stored?.data_recebimento);
  const returnShipment = pickReturnShipment(returnData);
  const currentShipment = currentReturnShipment(returnData) || returnShipment;
  const returnShipmentId = shipmentIdOf(returnShipment);
  const currentShipmentId = shipmentIdOf(currentShipment);
  const historyById = new Map();
  async function shipmentHistory(shipmentId) {
    if (!historyById.has(shipmentId)) {
      const result = await optionalMlGet(
        accessToken,
        '/shipments/' + encodeURIComponent(shipmentId) + '/history',
        'return_shipment_history'
      );
      optionalResults.push(result);
      historyById.set(shipmentId, result);
    }
    return historyById.get(shipmentId);
  }

  let shipmentSample = null;
  let firstLegInfo = null;
  if (returnShipmentId && (!buyerShippedAt || !receivedAt)) {
    const historyResult = await shipmentHistory(returnShipmentId);
    firstLegInfo = shipmentInfo(historyResult.data);

    // Segunda fonte (o próprio envio) só quando o histórico falhou ou veio num
    // formato desconhecido. Com date_history, a chamada extra não é feita.
    let shipmentData = null;
    if (!firstLegInfo.recognized) {
      const shipmentResult = await optionalMlGet(
        accessToken,
        '/shipments/' + encodeURIComponent(returnShipmentId),
        'return_shipment'
      );
      optionalResults.push(shipmentResult);
      shipmentData = shipmentResult.data;
      firstLegInfo = mergeShipmentInfo(firstLegInfo, shipmentInfo(shipmentData));
    }

    buyerShippedAt = buyerShippedAt || firstLegInfo.shipped;
    receivedAt = receivedAt || firstLegInfo.delivered;

    // Amostra só quando a data deveria existir e não foi lida: resposta em
    // formato desconhecido, ou envio já postado/entregue sem a data. Pacote
    // ainda no ponto de coleta (ready_to_ship) não tem data mesmo: sem amostra.
    const legStatus = firstLegInfo.status || lower(returnShipment?.status);
    const shouldHaveDates = ['shipped', 'delivered', 'refunded', 'reviewed'].includes(status)
      || ['shipped', 'delivered'].includes(lower(returnData.status));
    const unreadable = !firstLegInfo.recognized && shouldHaveDates && !firstLegInfo.shipped && !firstLegInfo.delivered;
    // Entregue com data de entrega e sem data de postagem acontece na API
    // (envio ao CD do ML): não gera amostra.
    const missingForStatus = firstLegInfo.recognized && (
      (legStatus === 'shipped' && !firstLegInfo.shipped)
      || (legStatus === 'delivered' && !firstLegInfo.delivered)
    );
    if (unreadable || missingForStatus) {
      shipmentSample = {
        claim_id: claimId,
        status_devolucao: lower(returnData.status),
        envios_na_devolucao: (Array.isArray(returnData.shipments) ? returnData.shipments : []).map((shipment) => ({
          tem_shipment_id: Boolean(shipment?.shipment_id),
          tem_id: Boolean(shipment?.id),
          status: shipment?.status ?? null,
          type: shipment?.type ?? null,
          destino: shipment?.destination?.name ?? null,
        })),
        historico: describeShape(historyResult.data),
        envio: describeShape(shipmentData),
      };
    }
  } else if (!returnShipmentId && ['shipped', 'delivered'].includes(lower(returnData.status))) {
    shipmentSample = {
      claim_id: claimId,
      status_devolucao: lower(returnData.status),
      sem_envio_na_devolucao: true,
      chaves_da_devolucao: Object.keys(returnData).slice(0, 40),
    };
  }

  const orderId = normalizeText(returnData.orders?.[0]?.order_id)
    || (lower(claim.resource) === 'order' ? normalizeText(claim.resource_id) : null)
    || normalizeText(stored?.order_id);

  // Pedido original: data da venda, anúncio, preço e tipo de logística, mais
  // SKU, quantidade, valor da venda, valor reembolsado e apelido (fila).
  // Busca enquanto faltar algum desses dados e, com a reclamação aberta, a cada
  // execução, porque o valor reembolsado muda até o caso encerrar.
  let saleDate = stored?.data_venda ? String(stored.data_venda).slice(0, 10) : null;
  let logisticType = lower(stored?.logistic_type);
  let values = {
    units: normalizeInteger(stored?.unidades_devolvidas),
    amount: normalizeNumber(stored?.valor_devolvido),
    mlbId: normalizeText(stored?.mlb_id),
    title: normalizeText(stored?.titulo_anuncio),
  };
  let orderValues = {
    sku: normalizeText(stored?.sku),
    quantidade: normalizeInteger(stored?.quantidade),
    valor_venda: normalizeNumber(stored?.valor_venda),
    valor_reembolsado: normalizeNumber(stored?.valor_reembolsado),
    comprador_apelido: normalizeText(stored?.comprador_apelido),
  };

  const needsOrderBase = !saleDate || !logisticType || values.amount === null || !values.mlbId;
  const needsOrderQueue = filaAvailable && (orderValues.valor_venda === null || claimOpen);
  if (orderId && (needsOrderBase || needsOrderQueue)) {
    const orderResult = await optionalMlGet(accessToken, '/orders/' + encodeURIComponent(orderId), 'order');
    optionalResults.push(orderResult);
    const order = orderResult.data;

    if (order) {
      const fromOrderQueue = orderQueueValues(order, returnData, orderId);
      orderValues = {
        sku: fromOrderQueue.sku || orderValues.sku,
        quantidade: fromOrderQueue.quantidade ?? orderValues.quantidade,
        valor_venda: fromOrderQueue.valor_venda ?? orderValues.valor_venda,
        valor_reembolsado: fromOrderQueue.valor_reembolsado ?? orderValues.valor_reembolsado,
        comprador_apelido: fromOrderQueue.comprador_apelido || orderValues.comprador_apelido,
      };
      saleDate = saleDate || saoPauloDate(order.date_created);
      const fromOrder = returnedValues(returnData, orderId, order);
      values = {
        units: values.units ?? fromOrder.units,
        amount: values.amount ?? fromOrder.amount,
        mlbId: values.mlbId || fromOrder.mlbId,
        title: values.title || fromOrder.title,
      };

      const shippingId = normalizeText(order.shipping?.id);
      if (!logisticType && shippingId) {
        const shipmentResult = await optionalMlGet(
          accessToken,
          '/shipments/' + encodeURIComponent(shippingId),
          'order_shipment'
        );
        optionalResults.push(shipmentResult);
        logisticType = logisticTypeOf(shipmentResult.data);
      }
    }
  }

  if (values.units === null || !values.mlbId) {
    const fromReturn = returnedValues(returnData, orderId, null);
    values.units = values.units ?? fromReturn.units;
    values.mlbId = values.mlbId || fromReturn.mlbId;
  }

  const returnUpdatedAt = normalizeDate(returnData.last_updated);
  const storedStatus = lower(stored?.status_atual);
  const statusChanged = Boolean(stored) && storedStatus !== status;

  // Quando a mudança de etapa é vista por esta ingestão e a API não trouxe a
  // data, usa a última atualização da devolução (no máximo 1 h de diferença).
  const observedAt = returnUpdatedAt || nowIso();
  const stage = stageOf(status);
  if (statusChanged && stage === 'enviada_pelo_comprador' && !buyerShippedAt) buyerShippedAt = observedAt;
  if (statusChanged && stage === 'recebida' && !receivedAt) receivedAt = observedAt;

  let refundedAt = normalizeDate(stored?.data_reembolso);
  if (status === 'refunded' && !refundedAt) {
    refundedAt = normalizeDate(returnData.refund_date ?? returnData.date_refunded) || observedAt;
  }

  const row = {
    account_id: accountId,
    claim_id: claimId,
    return_id: returnId,
    order_id: orderId,
    mlb_id: values.mlbId,
    titulo_anuncio: values.title,
    familia_motivo: reasonFamily(claim.reason_id),
    reason_id: normalizeText(claim.reason_id),
    status_atual: status,
    etapa_atual: stage,
    data_venda: saleDate,
    data_abertura: normalizeDate(returnData.date_created) || normalizeDate(claim.date_created),
    data_envio_comprador: buyerShippedAt,
    data_recebimento: receivedAt,
    data_reembolso: refundedAt,
    ultima_atualizacao: maxDate(claim.last_updated, claim.date_created, returnData.last_updated, returnData.date_created),
    unidades_devolvidas: values.units !== null && values.units >= 0 ? values.units : null,
    valor_devolvido: values.amount !== null && values.amount >= 0 ? values.amount : null,
    custo_frete_devolucao: returnCost,
    logistic_type: logisticType,
    synced_at: nowIso(),
  };

  // Colunas da fila (A–X da planilha). Gravadas só se a migração da fila já
  // foi rodada; senão o Supabase recusaria a gravação inteira.
  const actions = sellerActions(claim);
  let reviewSample = null;
  if (filaAvailable) {
    // Trecho atual do envio: rastreio, previsão e status de hoje. Com o caso
    // aberto, é lido a cada execução (uma chamada; reaproveita a do 1º trecho).
    let currentInfo = currentShipmentId && historyById.has(currentShipmentId)
      ? shipmentInfo(historyById.get(currentShipmentId).data)
      : null;
    if (!currentInfo && currentShipmentId && claimOpen) {
      currentInfo = shipmentInfo((await shipmentHistory(currentShipmentId)).data);
    }
    currentInfo = currentInfo || emptyShipmentInfo();
    currentInfo.status = currentInfo.status || lower(currentShipment?.status);

    const rawStatus = lower(returnData.status);
    const caseType = caseTypeOf(claim, true);
    const firstKind = destinationKind(returnShipment);
    const currentKind = destinationKind(currentShipment);
    const fromTriage = lower(currentShipment?.type) === 'return_from_triage';
    const hasReview = Boolean(reviewDate) || reviews.length > 0;
    const context = {
      claim, returnData, rawStatus, caseType, firstKind, currentKind, fromTriage,
      hasReview, reviewCondition, actions, shipment: currentInfo,
    };
    const pending = pendingActionOf(context);
    const inTransit = ['shipped', 'in_transit', 'label_generated', 'ready_to_ship', 'pending'].includes(rawStatus);
    const result = [
      reviewCondition ? REVIEW_CONDITION_LABELS[reviewCondition] || 'Revisão: ' + reviewCondition : null,
      resolutionTextOf(claim),
    ].filter(Boolean).join(' · ');

    Object.assign(row, {
      ...orderValues,
      etapa_ml: caseType,
      status_reclamacao: ['opened', 'closed'].includes(lower(claim.status)) ? lower(claim.status) : null,
      status_retorno: returnStatusTextOf(context),
      descricao_status: statusDescriptionOf(context),
      data_prevista: claimOpen && inTransit ? currentInfo.estimated : null,
      destino_retorno: destinationTextOf(currentKind || firstKind, true),
      rastreio: currentInfo.tracking
        || normalizeText(currentShipment?.tracking_number)
        || firstLegInfo?.tracking
        || normalizeText(stored?.rastreio),
      prazo_acao_vendedor: pending.dueDate,
      acao_pendente: pending.text,
      resultado: result || null,
    });

    // Revisão em formato desconhecido (sem product_condition): amostra das
    // chaves (nunca valores). Revisão ainda sem condição preenchida não conta.
    const reviewItems = reviews.flatMap((review) => (Array.isArray(review?.resource_reviews) ? review.resource_reviews : [review]));
    const knownReviewShape = reviewItems.some((item) => item && typeof item === 'object' && 'product_condition' in item);
    if (reviews.length && !reviewCondition && !knownReviewShape) {
      const firstReview = reviews[0] && typeof reviews[0] === 'object' ? reviews[0] : {};
      const firstItem = Array.isArray(firstReview.resource_reviews) ? firstReview.resource_reviews[0] : null;
      reviewSample = {
        claim_id: claimId,
        chaves_revisao: Object.keys(firstReview).slice(0, 40),
        chaves_item_revisado: firstItem && typeof firstItem === 'object' ? Object.keys(firstItem).slice(0, 40) : [],
      };
    }
  }

  return {
    kind: 'return',
    claimId,
    detailIssue,
    row,
    historyRows: buildHistoryRows(accountId, claimId, row, stored, reviewDate, returnUpdatedAt),
    statusChanged,
    shipmentSample,
    reviewSample,
    sellerActionCodes: actions.actions.map((item) => item.action + (item.mandatory ? ' (obrigatória)' : '')),
    sellerActionsKnown: actions.known,
    reviewCondition,
    rawStatus: lower(returnData.status),
    rawStatusMoney: lower(returnData.status_money),
    optionalErrors: optionalResults
      .filter((result) => result.error)
      .map((result) => ({ claim_id: claimId, endpoint: result.endpoint, error: result.error })),
    optionalNotFound: optionalResults
      .filter((result) => result.notFound)
      .map((result) => ({ claim_id: claimId, endpoint: result.endpoint })),
  };
}

function withoutQueueColumns(row) {
  return Object.fromEntries(Object.entries(row).filter(([key]) => !FILA_COLUMNS.includes(key)));
}

function dedupeBy(rows, keyOf) {
  const map = new Map();
  for (const row of rows) map.set(keyOf(row), row);
  return Array.from(map.values());
}

// Motivos novos: busca o nome uma vez por código. Nunca envia erro_operacional,
// para não apagar a classificação feita pelo cliente.
async function syncReasons(accountId, accessToken, reasonIds, knownReasonIds) {
  const missing = Array.from(new Set(reasonIds.filter(Boolean)))
    .filter((reasonId) => !knownReasonIds.has(reasonId));
  const rows = [];
  const errors = [];

  for (const reasonId of missing) {
    const result = await optionalMlGet(
      accessToken,
      '/post-purchase/v1/claims/reasons/' + encodeURIComponent(reasonId),
      'reason'
    );
    if (result.data && typeof result.data === 'object') {
      rows.push({
        account_id: accountId,
        reason_id: reasonId,
        familia: reasonFamily(reasonId),
        nome: normalizeText(result.data.name),
        detalhe: normalizeText(result.data.detail),
        synced_at: nowIso(),
      });
      knownReasonIds.add(reasonId);
    } else {
      errors.push({ reason_id: reasonId, not_found: result.notFound, error: result.error });
    }
    await sleep(requestDelayMs);
  }

  await upsertRows('devolucoes_motivos', rows, 'account_id,reason_id');
  return { synced: rows.length, errors };
}

// -----------------------------------------------------------------------------
// Execução
// -----------------------------------------------------------------------------
let accountsResponse;
try {
  accountsResponse = await supabaseRequest(
    'GET',
    '/oauth_tokens?select=account_id,refresh_token,access_token,expires_at,ml_user_id,accounts!inner(account_name,active)&accounts.active=eq.true'
  );
} catch (error) {
  throw new Error('Falha ao autenticar/consultar o Supabase: ' + JSON.stringify(compactError(error)));
}

let accounts = Array.isArray(accountsResponse) ? accountsResponse : [accountsResponse].filter(Boolean);
if (targetAccountId) accounts = accounts.filter((account) => String(account.account_id) === targetAccountId);
if (targetSellerId) accounts = accounts.filter((account) => String(account.ml_user_id || '') === targetSellerId);

if (!accounts.length) {
  return [{ json: { status: 'success', message: 'Nenhuma conta ativa encontrada.', processed: 0 } }];
}

const outputs = [];

for (const account of accounts) {
  const accountId = account.account_id;
  const accountName = account.accounts?.account_name || null;
  let runId = null;
  let syncRunLogError = null;

  try {
    if (!accountId) throw new Error('Linha de oauth_tokens sem account_id.');
    ({ runId, logError: syncRunLogError } = await startSyncRun(accountId));
    const { accessToken, sellerId } = await ensureAccessToken(account);
    const fromDate = new Date(Date.now() - claimsDaysBack * 24 * 60 * 60 * 1000);
    const toDate = new Date();

    let createdSearch;
    let updatedSearch;
    let openedSearch;
    let rangeFallbackUsed = false;

    try {
      createdSearch = await searchClaimsByRange(accessToken, sellerId, 'date_created', fromDate, toDate);
      updatedSearch = await searchClaimsByRange(accessToken, sellerId, 'last_updated', fromDate, toDate);
    } catch (rangeError) {
      if (errorStatus(rangeError) !== 400) throw rangeError;
      const sellerOpenedSearch = await searchClaims(accessToken, sellerId, { status: 'opened' });
      const sellerClosedSearch = await searchClaims(accessToken, sellerId, { status: 'closed' });
      createdSearch = { rows: [...sellerOpenedSearch.rows, ...sellerClosedSearch.rows], windows: 0 };
      updatedSearch = { rows: [], windows: 0 };
      openedSearch = sellerOpenedSearch;
      rangeFallbackUsed = true;
    }
    if (!openedSearch) {
      openedSearch = await searchClaims(accessToken, sellerId, { status: 'opened' });
    }

    const claimsMap = new Map();
    for (const claim of [...createdSearch.rows, ...updatedSearch.rows, ...openedSearch.rows]) {
      if (claim?.id) claimsMap.set(String(claim.id), claim);
    }

    // Com a migração da fila, lê também as colunas dela; sem, segue só com as
    // colunas do primeiro SQL (e não grava as da fila).
    let filaAvailable = true;
    let filaError = null;
    let storedRows;
    try {
      storedRows = await fetchPaged(
        'devolucoes',
        { select: DEVOLUCOES_COLUMNS + ',' + FILA_COLUMNS.join(','), account_id: 'eq.' + accountId },
        maxClaimsPerAccount * 2
      );
    } catch (error) {
      // Qualquer 400 aqui (o n8n nem sempre repassa o corpo com o código 42703):
      // se a leitura sem as colunas da fila funcionar, o problema são elas.
      if (!isMissingColumnError(error) && errorStatus(error) !== 400) throw error;
      filaAvailable = false;
      filaError = { etapa: 'leitura', ...compactError(error) };
      storedRows = await fetchPaged(
        'devolucoes',
        { select: DEVOLUCOES_COLUMNS, account_id: 'eq.' + accountId },
        maxClaimsPerAccount * 2
      );
    }
    const storedMap = new Map(storedRows.map((row) => [String(row.claim_id), row]));
    const knownReasons = await fetchPaged(
      'devolucoes_motivos',
      { select: 'reason_id', account_id: 'eq.' + accountId },
      10000
    );
    const knownReasonIds = new Set(knownReasons.map((row) => String(row.reason_id)));

    // Reclamações já conferidas sem devolução. A busca do Mercado Livre não diz
    // se a reclamação tem devolução; sem este controle, elas seriam conferidas de
    // novo a cada execução e a carga inicial nunca terminaria.
    let noReturnControlAvailable = true;
    let noReturnRows = [];
    try {
      noReturnRows = await fetchPaged(
        'devolucoes_claims_sem_devolucao',
        { select: 'claim_id,ultima_atualizacao', account_id: 'eq.' + accountId },
        maxClaimsPerAccount * 4
      );
    } catch (error) {
      noReturnControlAvailable = false;
    }
    const noReturnMap = new Map(noReturnRows.map((row) => [String(row.claim_id), row.ultima_atualizacao]));

    let claimsWithoutReturn = 0;
    const claimsNeedingSync = [];
    for (const claim of claimsMap.values()) {
      const claimId = String(claim.id);
      const stored = storedMap.get(claimId);
      if (!stored) {
        // Sem devolução segundo a busca, ou já conferida e sem mudança desde então.
        const searchSaysNoReturn = Array.isArray(claim.related_entities) && !claimHasReturn(claim);
        const checkedNoReturn = noReturnMap.has(claimId)
          && timeOf(claim.last_updated || claim.date_created) <= timeOf(noReturnMap.get(claimId));
        if (searchSaysNoReturn || checkedNoReturn) {
          claimsWithoutReturn += 1;
          continue;
        }
      }
      // Devolução gravada antes da migração da fila (status_reclamacao vazio):
      // é processada de novo uma vez, para preencher as colunas da fila.
      const queueMissing = filaAvailable && Boolean(stored) && !stored.status_reclamacao;
      if (!stored
        || lower(claim.status) === 'opened'
        || timeOf(claim.last_updated) > timeOf(stored.ultima_atualizacao)
        || queueMissing) {
        claimsNeedingSync.push(claim);
      }
    }

    // Em aberto primeiro (é o que o Acompanhamento mostra), depois as mais recentes.
    claimsNeedingSync.sort((left, right) => {
      const leftOpen = lower(left.status) === 'opened' ? 1 : 0;
      const rightOpen = lower(right.status) === 'opened' ? 1 : 0;
      if (leftOpen !== rightOpen) return rightOpen - leftOpen;
      return timeOf(right.last_updated || right.date_created) - timeOf(left.last_updated || left.date_created);
    });

    const claims = claimsNeedingSync.slice(0, maxClaimsToProcessPerRun);
    const claimsDeferred = Math.max(claimsNeedingSync.length - claims.length, 0);

    const baseErrors = [];
    const optionalErrors = [];
    const optionalNotFound = [];
    const detailIssues = [];
    const statusCounts = {};
    const rawStatusCounts = {};
    const unmappedStatuses = new Set();
    const reasonIds = [];
    const shipmentSamples = [];
    const reviewSamples = [];
    const sellerActionCounts = {};
    const reviewConditionCounts = {};
    const queueStatusCounts = {};
    const queueFilled = Object.fromEntries(FILA_COLUMNS.map((column) => [column, 0]));
    let claimsWithoutPlayers = 0;
    let queueRowsAccepted = 0;
    let queueRowsRefused = 0;
    const queueRefusedExamples = [];
    let returnsUpserted = 0;
    let returnsNew = 0;
    let statusChanges = 0;
    let historyRowsWritten = 0;
    let claimsCheckedWithoutReturn = 0;
    let returnErrors = 0;

    for (const batch of chunkArray(claims, claimConcurrency)) {
      const processed = await Promise.all(batch.map(async (claim) => {
        try {
          const value = await processClaim(
            accountId,
            accessToken,
            claim,
            storedMap.get(String(claim.id)),
            { filaAvailable }
          );
          return { ok: true, value };
        } catch (error) {
          return { ok: false, claim_id: String(claim.id), error: compactError(error) };
        }
      }));

      const returnResults = [];
      const noReturnResults = [];
      for (const result of processed) {
        if (!result.ok) {
          baseErrors.push({ claim_id: result.claim_id, error: result.error });
          continue;
        }
        const value = result.value;
        if (value.detailIssue) detailIssues.push(value.detailIssue);
        optionalErrors.push(...(value.optionalErrors || []));
        optionalNotFound.push(...(value.optionalNotFound || []));
        if (value.kind === 'no_return') {
          claimsCheckedWithoutReturn += 1;
          noReturnResults.push(value);
        }
        if (value.kind === 'return_error') returnErrors += 1;
        if (value.kind === 'return') returnResults.push(value);
      }

      const rows = dedupeBy(returnResults.map((value) => value.row), (row) => row.claim_id);
      const historyRows = dedupeBy(
        returnResults.flatMap((value) => value.historyRows),
        (row) => [row.claim_id, row.status, row.data_status].join('|')
      );

      // devolucoes antes do histórico (chave estrangeira). Se o Supabase recusar
      // o lote com as colunas da fila (400), grava linha a linha: as aceitas
      // ficam com a fila; as recusadas são gravadas sem ela e aparecem em
      // fila_linhas_recusadas, com o motivo. Se as 5 primeiras forem todas
      // recusadas, o problema é geral: o resto da execução segue sem a fila.
      try {
        await upsertRows('devolucoes', rows, 'account_id,claim_id');
        if (filaAvailable) queueRowsAccepted += rows.length;
      } catch (error) {
        if (!filaAvailable || errorStatus(error) !== 400) throw error;
        filaError = filaError || { etapa: 'gravacao', ...compactError(error) };
        for (const row of rows) {
          if (filaAvailable) {
            try {
              await upsertRows('devolucoes', [row], 'account_id,claim_id');
              queueRowsAccepted += 1;
              continue;
            } catch (rowError) {
              if (errorStatus(rowError) !== 400) throw rowError;
              queueRowsRefused += 1;
              if (queueRefusedExamples.length < 3) {
                const queueValues = Object.fromEntries(FILA_COLUMNS
                  .filter((column) => column !== 'comprador_apelido')
                  .map((column) => [column, row[column]]));
                queueRefusedExamples.push({ claim_id: row.claim_id, erro: compactError(rowError), valores_fila: queueValues });
              }
              if (queueRowsAccepted === 0 && queueRowsRefused >= 5) filaAvailable = false;
            }
          }
          await upsertRows('devolucoes', [withoutQueueColumns(row)], 'account_id,claim_id');
        }
      }
      await upsertRows('devolucoes_status', historyRows, 'account_id,claim_id,status,data_status');

      if (noReturnControlAvailable && noReturnResults.length) {
        await upsertRows(
          'devolucoes_claims_sem_devolucao',
          dedupeBy(noReturnResults.map((value) => ({
            account_id: accountId,
            claim_id: value.claimId,
            ultima_atualizacao: value.claimUpdatedAt,
            verificado_em: nowIso(),
          })), (row) => row.claim_id),
          'account_id,claim_id'
        );
      }

      for (const value of returnResults) {
        if (!storedMap.has(value.claimId)) returnsNew += 1;
        if (value.statusChanged) statusChanges += 1;
        storedMap.set(value.claimId, value.row);
        const status = value.row.status_atual || '(vazio)';
        statusCounts[status] = (statusCounts[status] || 0) + 1;
        const rawKey = (value.rawStatus || '(vazio)') + ' / money=' + (value.rawStatusMoney || '(vazio)');
        rawStatusCounts[rawKey] = (rawStatusCounts[rawKey] || 0) + 1;
        if (!value.row.etapa_atual) unmappedStatuses.add(status);
        if (value.row.reason_id) reasonIds.push(value.row.reason_id);
        if (value.shipmentSample && shipmentSamples.length < 3) shipmentSamples.push(value.shipmentSample);
        if (filaAvailable) {
          if (value.reviewSample && reviewSamples.length < 2) reviewSamples.push(value.reviewSample);
          for (const code of value.sellerActionCodes) {
            sellerActionCounts[code] = (sellerActionCounts[code] || 0) + 1;
          }
          if (value.row.status_reclamacao === 'opened' && !value.sellerActionsKnown) claimsWithoutPlayers += 1;
          if (value.reviewCondition) {
            reviewConditionCounts[value.reviewCondition] = (reviewConditionCounts[value.reviewCondition] || 0) + 1;
          }
          if (value.row.status_reclamacao === 'opened') {
            const label = value.row.status_retorno || '(vazio)';
            queueStatusCounts[label] = (queueStatusCounts[label] || 0) + 1;
          }
          for (const column of FILA_COLUMNS) {
            if (value.row[column] !== null && value.row[column] !== undefined) queueFilled[column] += 1;
          }
        }
      }
      returnsUpserted += rows.length;
      historyRowsWritten += historyRows.length;

      await sleep(requestDelayMs);
    }

    const reasonsResult = await syncReasons(accountId, accessToken, reasonIds, knownReasonIds);

    const finalStatus = baseErrors.length ? 'error' : 'success';
    const runError = baseErrors.length
      ? new Error(baseErrors.length + ' claim(s) falharam. Primeiro: ' + JSON.stringify(baseErrors[0]))
      : null;
    const finishLogError = await finishSyncRun(runId, finalStatus, runError);

    const optionalErrorsByEndpoint = {};
    for (const item of optionalErrors) {
      optionalErrorsByEndpoint[item.endpoint] = (optionalErrorsByEndpoint[item.endpoint] || 0) + 1;
    }
    const notFoundByEndpoint = {};
    for (const item of optionalNotFound) {
      notFoundByEndpoint[item.endpoint] = (notFoundByEndpoint[item.endpoint] || 0) + 1;
    }

    const allRows = Array.from(storedMap.values());
    const missing = (column) => allRows.filter((row) => row[column] === null || row[column] === undefined).length;

    outputs.push({
      json: {
        status: baseErrors.length ? 'partial_success' : 'success',
        account_id: accountId,
        account_name: accountName,
        seller_id: sellerId,
        window_days: claimsDaysBack,
        range_fallback_used: rangeFallbackUsed,
        search_created_windows: createdSearch.windows,
        search_updated_windows: updatedSearch.windows,
        search_opened_rows: openedSearch.rows.length,
        claims_found: claimsMap.size,
        claims_without_return_skipped: claimsWithoutReturn,
        controle_sem_devolucao_disponivel: noReturnControlAvailable,
        claims_needing_sync: claimsNeedingSync.length,
        claims_processed: claims.length,
        claims_deferred: claimsDeferred,
        claims_checked_without_return: claimsCheckedWithoutReturn,
        returns_upserted: returnsUpserted,
        returns_new: returnsNew,
        status_changes: statusChanges,
        history_rows_written: historyRowsWritten,
        reasons_synced: reasonsResult.synced,
        reason_errors: reasonsResult.errors.slice(0, 10),
        // Mande estes dois campos para ajustar o mapeamento de etapas no painel.
        status_atual_desta_execucao: statusCounts,
        status_bruto_da_api: rawStatusCounts,
        status_sem_etapa: Array.from(unmappedStatuses),
        total_devolucoes_no_banco: allRows.length,
        faltando_no_banco: {
          data_venda: missing('data_venda'),
          logistic_type: missing('logistic_type'),
          valor_devolvido: missing('valor_devolvido'),
          custo_frete_devolucao: missing('custo_frete_devolucao'),
          data_envio_comprador: missing('data_envio_comprador'),
          data_recebimento: missing('data_recebimento'),
          ...(filaAvailable ? {
            status_reclamacao: missing('status_reclamacao'),
            sku: missing('sku'),
            valor_venda: missing('valor_venda'),
          } : {}),
        },
        // Fila (Acompanhamento). false = rode o SQL 2026-10-08_devolucoes_fila.sql.
        colunas_fila_disponiveis: filaAvailable,
        // Motivo de a fila ter ficado de fora nesta execução (mande para ajuste).
        fila_erro: filaError,
        fila_linhas_recusadas: queueRowsRefused,
        fila_exemplos_recusados: queueRefusedExamples,
        fila_preenchida_nesta_execucao: filaAvailable ? queueFilled : null,
        fila_status_retorno_abertas: filaAvailable ? queueStatusCounts : null,
        // Mande estes campos para ajustar as traduções de ação e resultado.
        acoes_vendedor_vistas: filaAvailable ? sellerActionCounts : null,
        abertas_sem_participantes: filaAvailable ? claimsWithoutPlayers : null,
        condicoes_revisao_vistas: filaAvailable ? reviewConditionCounts : null,
        amostra_revisao: reviewSamples,
        // Só aparece se uma data de envio que já deveria existir não for lida.
        amostra_envio_devolucao: shipmentSamples,
        detail_restricted_or_unavailable: detailIssues.length,
        return_errors: returnErrors,
        base_errors: baseErrors.length,
        base_error_examples: baseErrors.slice(0, 10),
        optional_errors_by_endpoint: optionalErrorsByEndpoint,
        optional_error_examples: optionalErrors.slice(0, 10),
        optional_not_found_by_endpoint: notFoundByEndpoint,
        sync_run_id: runId,
        sync_run_log_error: syncRunLogError || finishLogError,
      },
    });
  } catch (error) {
    const logError = await finishSyncRun(runId, 'error', error);
    outputs.push({
      json: {
        status: 'error',
        account_id: accountId || null,
        account_name: accountName,
        error: compactError(error),
        sync_run_id: runId,
        sync_run_log_error: syncRunLogError || logError,
      },
    });
  }
}

return outputs;
